import{_ as o,o as a,c as r,ag as t}from"./chunks/framework.BYYsWsaA.js";const u=JSON.parse('{"title":"Organizing with Folders","description":"","frontmatter":{},"headers":[],"relativePath":"pdf/organizing-with-folders.md","filePath":"pdf/organizing-with-folders.md"}'),n={name:"pdf/organizing-with-folders.md"};function l(s,e,i,d,c,h){return a(),r("div",null,[...e[0]||(e[0]=[t('<h1 id="organizing-with-folders" tabindex="-1">Organizing with Folders <a class="header-anchor" href="#organizing-with-folders" aria-label="Permalink to &quot;Organizing with Folders&quot;">​</a></h1><p>Folders let you organize a workspace&#39;s documents into a tree — the same way a Shared Drive works. Folders are <strong>purely organizational</strong>: they group documents for browsing but do not change who can access a document.</p><p>Every document type can live in a folder — sheets, docs, slides, notes, PDFs, and images alike.</p><h2 id="create-a-folder" tabindex="-1">Create a folder <a class="header-anchor" href="#create-a-folder" aria-label="Permalink to &quot;Create a folder&quot;">​</a></h2><ol><li>Open your workspace</li><li>Click <strong>New folder</strong></li><li>Give it a name</li></ol><p>Folders can be nested to any depth, so you can build a structure like <code>Team → Projects → 2026</code>.</p><h2 id="move-documents-and-folders" tabindex="-1">Move documents and folders <a class="header-anchor" href="#move-documents-and-folders" aria-label="Permalink to &quot;Move documents and folders&quot;">​</a></h2><ul><li>Use <strong>Move to…</strong> on a document (or folder) to relocate it into another folder, or back to the workspace root.</li><li>Moving a folder brings all of its contents along with it.</li></ul><h2 id="browse-folders" tabindex="-1">Browse folders <a class="header-anchor" href="#browse-folders" aria-label="Permalink to &quot;Browse folders&quot;">​</a></h2><ul><li><strong>Click a folder</strong> to drill into it and see the documents inside.</li><li>The <strong>breadcrumb</strong> at the top shows where you are; click any segment to jump back up the tree.</li><li>The workspace root is the top level — documents that aren&#39;t in any folder live there.</li></ul><h2 id="rename-a-folder" tabindex="-1">Rename a folder <a class="header-anchor" href="#rename-a-folder" aria-label="Permalink to &quot;Rename a folder&quot;">​</a></h2><p>Use <strong>Rename folder</strong> to change a folder&#39;s name. Any member of the workspace can rename a folder.</p><h2 id="delete-a-folder" tabindex="-1">Delete a folder <a class="header-anchor" href="#delete-a-folder" aria-label="Permalink to &quot;Delete a folder&quot;">​</a></h2><p>Deleting a folder removes the folder and its sub-folders, but <strong>never deletes your documents</strong> — any documents inside return to the workspace root so nothing is lost.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Folders only organize documents; they don&#39;t grant or restrict access. Sharing and permissions are controlled per-document — see <a href="/docs/guide/collaboration.html">Collaboration &amp; Sharing</a>.</p></div>',15)])])}const m=o(n,[["render",l]]);export{u as __pageData,m as default};
